/**
 * A2A skill emission: one authored `A2ASkill` entry → its
 * `elementum_agent_a2a_skill` resource block. Unlike agent tools, an A2A
 * skill carries no `app_id` and no target/field references — it's pure
 * metadata (name/description/tags/examples/input+output modes) describing
 * what the agent offers to OTHER agents (provider/docs/resources/
 * agent_a2a_skill.md). Owner passed in — this module never names the
 * owning app.
 */
import { appScopedResourceLabel, expr, sanitizeName } from "../../engine/tf/index.js";
import { AGENT_A2A_SKILL_RESOURCE_TYPE } from "./module.js";
/** One authored `A2ASkill` entry → its resource block; undefined = degraded (diagnostic already pushed). */
export function a2aSkillToTf(entry, ctx) {
    const name = entry.name ?? "";
    if (name === "") {
        ctx.diagnostics.push("a2a skill entry has no name; dropped");
        return undefined;
    }
    const where = `a2a skill "${name}"`;
    if (entry.description === undefined || entry.description === "") {
        ctx.diagnostics.push(`${where}: description is required; dropped`);
        return undefined;
    }
    const agentTfLabel = appScopedResourceLabel(ctx.appTfLabel, ctx.agentBareTfLabel);
    // edk#286: ei's own export scopes an a2a skill's label by the APP only
    // (apps_<ns>_<ns>_<skill-name>) — no owning-agent segment, unlike agent
    // tools. Confirmed live; a prior version of this line prefixed
    // ctx.agentBareTfLabel here, which build-vs-export never actually
    // matched (only became visible once a fully successful agent-adoption
    // cycle reached that check).
    const tfLabel = appScopedResourceLabel(ctx.appTfLabel, `${sanitizeName(name)}${ctx.labelSuffix ?? ""}`);
    const attrs = {
        agent_id: expr.resourceAttr("elementum_agent", agentTfLabel, ["id"]),
        name,
        description: entry.description,
    };
    if (entry.tags !== undefined && entry.tags.length > 0)
        attrs["tags"] = [...entry.tags].sort();
    if (entry.examples !== undefined && entry.examples.length > 0)
        attrs["examples"] = [...entry.examples].sort();
    if (entry.inputModes !== undefined && entry.inputModes.length > 0)
        attrs["input_modes"] = [...entry.inputModes].sort();
    if (entry.outputModes !== undefined && entry.outputModes.length > 0)
        attrs["output_modes"] = [...entry.outputModes].sort();
    const block = { kind: "resource", type: AGENT_A2A_SKILL_RESOURCE_TYPE, label: tfLabel, attrs };
    return { block, address: `${AGENT_A2A_SKILL_RESOURCE_TYPE}.${tfLabel}` };
}
